      "activity_id": "A8.1",
      "activity_name": "Design admin artifact split and module structure",
      "activity_description": "Determine how to split the admin artifact into separate modules, each with specific Hadoop version dependencies.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Refactor code into separate modules",
